// ============================================================
// PhotonBoard — demo content shipped with the app (resources/demos,
// generated by scripts/build-demos.ts): demo shows (File › Open a
// demo…) and one example file per import format (import wizard ›
// Try with an example file). Main reads the manifest
// (src/main/demos.ts); the console UI lists it.
// ============================================================

/** A text in both UI languages */
export interface DemoText {
  en: string
  fr: string
}

/** resources/demos/demos.json */
export interface DemoManifest {
  version: 1
  shows: {
    id: string
    /** File name in resources/demos */
    file: string
    /** Show name (data: never translated) */
    name: string
    description: DemoText
    fixtures: number
    universes: number
  }[]
  formats: {
    id: string
    /** Path relative to resources/demos ("formats/Club Night.mvr") */
    file: string
    /** Interchange format id (src/shared/interchange.ts) */
    format: string
    description: DemoText
  }[]
}

export interface DemoShowInfo {
  id: string
  name: string
  description: DemoText
  fixtures: number
  universes: number
}

export interface DemoFormatFile {
  id: string
  fileName: string
  /** Absolute path (console only): imported like a dropped file */
  path: string
  format: string
  description: DemoText
  size: number
}

export interface DemoList {
  shows: DemoShowInfo[]
  formats: DemoFormatFile[]
}

/** The text in `locale`, English otherwise */
export function demoText(text: DemoText | undefined, locale: string): string {
  if (!text) return ''
  return (locale === 'fr' ? text.fr : text.en) || text.en || text.fr || ''
}
